/// or URL fragment. Returns the last path segment when it is non-empty,
/// or `None` when the URL ends in a trailing slash (an empty last
/// segment) or otherwise carries no usable basename.
///
/// Used by [`rewrite_tarball_urls`] to preserve an upstream tarball's
/// own filename in the rewritten URL rather than reconstructing the
/// conventional `<name>-<version>.tgz`, so a non-canonically named
/// tarball round-trips through the proxy verbatim.
///
/// ```text
/// "https://r/foo/-/foo-1.0.0.tgz"        -> Some("foo-1.0.0.tgz")
/// "https://r/foo/-/foo-1.0.0.tgz?sig=x"  -> Some("foo-1.0.0.tgz")
/// "https://r/foo/-/foo-1.0.0.tgz#frag"   -> Some("foo-1.0.0.tgz")
/// "foo-1.0.0.tgz"                        -> Some("foo-1.0.0.tgz")
/// "https://r/foo/"                       -> None
/// ```
pub fn tarball_basename(url: &str) -> Option<&str> {
    let path = url.split(|ch| ch == '?' || ch == '#').next().unwrap_or(url);
    let basename = path.rsplit('/').next().unwrap_or(path);
    (!basename.is_empty()).then_some(basename)
}

