}", "newString": "/// Resolve which packument version a tarball request for `filename` (a
/// `dist.tarball` basename) refers to, returning that version's key and
/// parsed integrity.
///
/// The route binds to the declaring version's `dist.tarball` basename
/// rather than to any version string embedded in the filename, so a
/// tarball named `foo-2.0.0.tgz` that version `1.0.0` declares resolves
/// to `1.0.0` — and to `1.0.0`'s integrity, cache key, and upstream
/// path. A version whose `dist.tarball` carries no usable basename falls
/// back to the conventional `<name>-<version>.tgz`, mirroring
/// [`rewrite_tarball_urls`] so the round-trip stays consistent.
///
/// Returns:
/// * `Ok(Some(..))` — exactly one version declares `filename`.
/// * `Ok(None)` — no version declares it (surfaces as 404).
/// * `Err(..)` — two versions declare the same basename (an ambiguous
///   upstream packument; surfaces as 502 before any tarball fetch), or
///   the declaring version's `dist.integrity` is missing/malformed.
fn resolve_tarball_route(
    packument: &[u8],
    name: &PackageName,
    filename: &str,
) -> Result<Option<(String, Integrity)>, RegistryError> {
    let packument: Value = serde_json::from_slice(packument)?;
    let Some(versions) = packument.get("versions").and_then(Value::as_object) else {
        return Ok(None);
    };
    let mut matched: Option<(&String, &Value)> = None;
    for (version, manifest) in versions {
        let declared_basename = manifest
            .get("dist")
            .and_then(|dist| dist.get("tarball"))
            .and_then(Value::as_str)
            .and_then(tarball_basename);
        let basename = match declared_basename {
            Some(basename) => basename.to_owned(),
            None => name.tarball_name_for_version(version),
        };
        if basename != filename {
            continue;
        }
        if matched.is_some() {
            return Err(tarball_integrity_error(
                name,
                filename,
                "multiple versions declare this tarball basename".to_string(),
            ));
        }
        matched = Some((version, manifest));
    }
    let Some((version, manifest)) = matched else {
        return Ok(None);
    };
    let declared = manifest
        .get("dist")
        .and_then(|dist| dist.get("integrity"))
        .and_then(Value::as_str)
        .ok_or_else(|| {
            tarball_integrity_error(
                name,
                filename,
                format!("packument has no dist.integrity for version {version:?}"),
            )
        })?;
    let integrity = streaming::parse_integrity(declared).map_err(|err| {
        tarball_integrity_error(name, filename, format!("malformed dist.integrity: {err}"))
    })?;
    Ok(Some((version.clone(), integrity)))
